const $=s=>document.querySelector(s),message=$('#message');let page=1,loading=false,sequence=0;
const statuses={new:'New',contacted:'Contacted',discussion:'Family discussion',admitted:'Admitted',closed:'Closed'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>new Date(v).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Kolkata'});
function signedIn(yes){$('#login').hidden=yes;$('#dashboard').hidden=!yes;$('#logout').hidden=!yes;if(!yes){$('#leads').replaceChildren();$('#stats').replaceChildren();}}
async function api(method='GET',body,query=''){const r=await fetch('/api/founders'+query,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok){if(r.status===401&&method!=='POST')signedIn(false);throw Error(data.error||'Please try again.');}return data;}
async function load(){const seq=++sequence;loading=true;$('#refresh').disabled=true;message.textContent='';try{const query=new URLSearchParams(new FormData($('#filters')));query.set('page',page);const data=await api('GET',null,'?'+query);if(seq!==sequence)return;signedIn(true);$('#stats').innerHTML=[['All enquiries',data.summary.total],['New enquiries',data.summary.new],['Following up',data.summary.following_up],['Admitted',data.summary.admitted]].map(([label,value])=>`<div class="stat"><span>${label}</span><strong>${value}</strong></div>`).join('');$('#count').textContent=`${data.total} matching enquiries`;$('#page').textContent=`Page ${page} of ${Math.max(1,Math.ceil(data.total/30))}`;$('#prev').disabled=page<=1;$('#next').disabled=page*30>=data.total;
$('#leads').innerHTML=data.leads.length?data.leads.map(l=>`<details class="lead"><summary><div><strong>${esc(l.child_name)}</strong><small>${esc(l.parent_name)} · ${esc(l.upcoming_grade)} · ${esc(date(l.created_at))} IST</small></div><span class="badge">${esc(statuses[l.status]||l.status)}</span></summary><div class="details"><div><dl>${[['Parent / guardian',l.parent_name],['Mobile',l.mobile],['Locality',l.locality],['Campus',['Playway','Nursery','LKG','UKG'].includes(l.upcoming_grade)?'Kidsverse Campus':'Stone Field Campus'],['Upcoming grade',l.upcoming_grade],['Current grade',l.current_grade],['Current school',l.current_school],['Kidsverse student',l.kidsverse_student?'Yes':'No'],['Last updated',date(l.updated_at)+' IST']].map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl><div class="actions"><a href="tel:+91${esc(l.mobile)}">Call parent ↗</a><a href="https://wa.me/91${esc(l.mobile)}" target="_blank" rel="noopener noreferrer">WhatsApp ↗</a></div></div><form class="edit" data-id="${esc(l.id)}"><label>Follow-up status<select name="status">${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${k===l.status?'selected':''}>${v}</option>`).join('')}</select></label><label>Private founder notes<textarea name="notes" maxlength="2000" placeholder="Discussion notes and next steps">${esc(l.founder_notes)}</textarea></label><button class="gold">Save follow-up</button></form></div></details>`).join(''):'<p class="empty">No enquiries match these filters.</p>';
}catch(e){if(seq===sequence)message.textContent=e.message;}finally{loading=false;$('#refresh').disabled=false;}}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;message.textContent='';try{await api('POST',{passcode:$('#passcode').value});$('#passcode').value='';page=1;await load();}catch(e){message.textContent=e.message;}finally{b.disabled=false;}});
$('#logout').addEventListener('click',async()=>{try{await api('DELETE');sequence++;signedIn(false);message.textContent='Signed out.';}catch(e){message.textContent=e.message;}});
$('#filters').addEventListener('submit',e=>{e.preventDefault();page=1;load();});$('#refresh').addEventListener('click',()=>load());$('#prev').addEventListener('click',()=>{if(!loading){page--;load();}});$('#next').addEventListener('click',()=>{if(!loading){page++;load();}});
$('#leads').addEventListener('submit',async e=>{if(!e.target.matches('.edit'))return;e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api('PATCH',{id:e.target.dataset.id,...Object.fromEntries(new FormData(e.target))});await load();message.textContent='Follow-up saved.';}catch(e){message.textContent=e.message;}finally{b.disabled=false;}});
load();
